module traffic(clk, rst, light);
  input clk;
  input rst;
  output [1:0] light;

  reg [1:0] state;
  reg [7:0] timer;

  wire timer_expired = (timer == 8'd0);

  assign light = state;

  always @(posedge clk) begin
    if (rst) begin
      state <= 2'b00;
      timer <= 8'd20;
    end else begin
      if (timer_expired) begin
        case (state)
          2'b00: begin
            state <= 2'b01;
            timer <= 8'd15;
          end
          2'b01: begin
            state <= 2'b10;
            timer <= 8'd20;
          end
          2'b10: begin
            state <= 2'b00;
            timer <= 8'd20;
          end
          default: begin
            state <= 2'b00;
            timer <= 8'd0;
          end
        endcase
      end else begin
        timer <= timer - 8'd1;
      end
    end
  end
endmodule

